import re

def _parse_int(s):
    if s is None or str(s).strip() in ('', '-'):
        return None
    try:
        return int(s)
    except ValueError:
        return None

def _parse_float(s):
    if s is None or str(s).strip() in ('', '-'):
        return None
    try:
        return float(s)
    except ValueError:
        return None

def _find_node(nodes, title):
    for n in nodes:
        if n.get('title') == title:
            return n
    return None

def entities(doc, scope):
    nodes = scope_nodes(doc, scope)
    machines_node = _find_node(nodes, f"{scope}: Machines")
    tasks_node = _find_node(nodes, f"{scope}: Task log")
    res = []
    if machines_node:
        for _, row in table_rows(machines_node):
            mid = row.get('machine', '')
            if mid:
                res.append({"id": mid, "description": f"Machine {mid}"})
    if tasks_node:
        seen = set()
        for _, row in table_rows(tasks_node):
            tid = row.get('task', '')
            if tid and tid not in seen:
                seen.add(tid)
                res.append({"id": tid, "description": f"Task {tid}"})
    return res

def recorded_end(doc, scope):
    return 1200.0

def inputs(doc, scope):
    nodes = scope_nodes(doc, scope)
    machines_node = _find_node(nodes, f"{scope}: Machines")
    tasks_node = _find_node(nodes, f"{scope}: Task log")
    res = []
    if machines_node:
        for ridx, row in table_rows(machines_node):
            mid = row.get('machine', '')
            if mid:
                res.append({
                    "id": f"{mid}_spec",
                    "time": 0.0,
                    "kind": "machine_spec",
                    "entities": [mid],
                    "fields": {
                        "CPU": _parse_int(row.get('CPU')),
                        "memory": _parse_int(row.get('memory')),
                        "fails_at": _parse_int(row.get('fails at')),
                        "returns_at": _parse_int(row.get('returns at'))
                    },
                    "src": [[machines_node['node_id'], ridx]]
                })
    if tasks_node:
        for ridx, row in table_rows(tasks_node):
            if row.get('event') == 'submit':
                tid = row.get('task', '')
                if tid:
                    res.append({
                        "id": f"{tid}_submit",
                        "time": _parse_float(row.get('time')),
                        "kind": "task_submit",
                        "entities": [tid],
                        "fields": {
                            "job": row.get('job'),
                            "priority": _parse_int(row.get('priority')),
                            "CPU": _parse_int(row.get('CPU')),
                            "memory": _parse_int(row.get('memory')),
                            "run_time": _parse_int(row.get('run time'))
                        },
                        "src": [[tasks_node['node_id'], ridx]]
                    })
    return res

def outcomes(doc, scope):
    nodes = scope_nodes(doc, scope)
    tasks_node = _find_node(nodes, f"{scope}: Task log")
    events_node = _find_node(nodes, f"{scope}: Events")
    queue_node = _find_node(nodes, f"{scope}: Queue at window end")
    res = []
    if tasks_node:
        for ridx, row in table_rows(tasks_node):
            event = row.get('event', '')
            if event in ('start', 'finish', 'evict', 'fail'):
                tid = row.get('task', '')
                mid = row.get('machine', '')
                ents = [tid]
                if mid and mid != '-':
                    ents.append(mid)
                res.append({
                    "time": _parse_float(row.get('time')),
                    "kind": f"task_{event}",
                    "entities": ents,
                    "value": None,
                    "src": [[tasks_node['node_id'], ridx]]
                })
    if events_node and 'lines' in events_node:
        for lidx, line in enumerate(events_node['lines']):
            time_match = re.match(r'Time\s+([\d.]+):', line)
            t = _parse_float(time_match.group(1)) if time_match else None
            ents = list(dict.fromkeys(re.findall(r'\bM\d+\b|\bT\d+\b', line)))
            res.append({
                "time": t,
                "kind": "event_log",
                "entities": ents,
                "value": None,
                "src": [[events_node['node_id'], lidx]]
            })
    if queue_node:
        for ridx, row in table_rows(queue_node):
            tid = row.get('task', '')
            mid = row.get('machine', '')
            ents = [tid]
            if mid and mid != '-':
                ents.append(mid)
            remaining = _parse_int(row.get('remaining', '0'))
            res.append({
                "time": 1200.0,
                "kind": "queue_state",
                "entities": ents,
                "value": remaining,
                "src": [[queue_node['node_id'], ridx]]
            })
    return res

def params(doc, scope):
    return {"window_length": 1200, "num_machines": 8}


# ---- step 2: forward model ----
import heapq
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None: start = 0
    if horizon is None: horizon = params.get('window_length', 1200)

    machines = {}
    task_submits = []
    for inp in inputs:
        if inp['kind'] == 'machine_spec':
            mid = inp['entities'][0]
            machines[mid] = {
                'total_cpu': inp['fields']['CPU'],
                'total_mem': inp['fields']['memory'],
                'fails_at': inp['fields']['fails_at'],
                'returns_at': inp['fields']['returns_at'],
            }
        elif inp['kind'] == 'task_submit':
            task_submits.append(inp)

    sorted_mids = sorted(machines.keys())

    task_info = {}
    running = {}  # mid -> {tid: started_time}
    for mid in sorted_mids:
        running[mid] = {}
    machine_up = {mid: True for mid in sorted_mids}
    machine_free_cpu = {mid: machines[mid]['total_cpu'] for mid in sorted_mids}
    machine_free_mem = {mid: machines[mid]['total_mem'] for mid in sorted_mids}

    outcomes = []
    waiting = []

    def parse_tid(t_str):
        return int(''.join(filter(str.isdigit, t_str)))

    def queue_key(tid):
        t = task_info[tid]
        return (-t['priority'], t['submit_time'], parse_tid(tid))

    def evict_sort_key(tid):
        t = task_info[tid]
        return (t['priority'], -t.get('_start_time', 0), -parse_tid(tid))

    event_times = set()
    event_times.add(0)
    for ts in task_submits:
        event_times.add(ts['time'])
    for mid, m in machines.items():
        if m['fails_at'] is not None: event_times.add(m['fails_at'])
        if m['returns_at'] is not None: event_times.add(m['returns_at'])

    event_heap = list(event_times)
    heapq.heapify(event_heap)
    processed_times = set()

    def add_finish_event(tid, mid, started):
        heapq.heappush(event_heap, started + task_info[tid]['run_time'])

    def process_finishes(t):
        for mid in sorted_mids:
            finished = []
            for tid, started in list(running[mid].items()):
                if started + task_info[tid]['run_time'] == t:
                    finished.append(tid)
            for tid in finished:
                task = task_info[tid]
                del running[mid][tid]
                machine_free_cpu[mid] += task['cpu']
                machine_free_mem[mid] += task['memory']
                outcomes.append({"time": t, "kind": "task_finish", "entities": [tid, mid], "value": None})

    def process_failures(t):
        for mid in sorted_mids:
            if machines[mid]['fails_at'] == t:
                machine_up[mid] = False
                for tid in list(running[mid].keys()):
                    task = task_info[tid]
                    machine_free_cpu[mid] += task['cpu']
                    machine_free_mem[mid] += task['memory']
                    task['_start_time'] = None
                    waiting.append(tid)
                    outcomes.append({"time": t, "kind": "task_fail", "entities": [tid, mid], "value": None})
                running[mid] = {}

    def process_returns(t):
        for mid in sorted_mids:
            if machines[mid]['returns_at'] == t:
                machine_up[mid] = True
                machine_free_cpu[mid] = machines[mid]['total_cpu']
                machine_free_mem[mid] = machines[mid]['total_mem']
                running[mid] = {}

    def process_submissions(t):
        for ts in task_submits:
            if ts['time'] == t:
                tid = ts['entities'][0]
                task_info[tid] = {
                    'priority': ts['fields']['priority'],
                    'cpu': ts['fields']['CPU'],
                    'memory': ts['fields']['memory'],
                    'run_time': ts['fields']['run_time'],
                    'submit_time': t,
                    '_start_time': None
                }
                waiting.append(tid)

    def can_fit(task, mid, cpu, mem):
        return cpu >= task['cpu'] and mem >= task['memory']

    def scheduling_round(t):
        nonlocal waiting
        nonlocal reservation_task, reservation_machine, reservation_time, backfill_cpu, backfill_mem

        if not waiting:
            reservation_task = None
            return

        reservation_task = None
        reservation_machine = None
        reservation_time = None
        backfill_cpu = 0
        backfill_mem = 0

        changed = True
        while changed:
            changed = False
            waiting.sort(key=queue_key)
            still_waiting = []
            newly_waiting = []

            for tid in waiting:
                task = task_info[tid]
                placed = False

                # a. First fit
                for mid in sorted_mids:
                    if not machine_up[mid]:
                        continue

                    cpu_avail = machine_free_cpu[mid]
                    mem_avail = machine_free_mem[mid]

                    # Check reservation constraint
                    if reservation_machine is not None and mid == reservation_machine:
                        if can_fit(task, mid, cpu_avail, mem_avail):
                            res_task = task_info[reservation_task]
                            finishes_by = (t + task['run_time'] <= reservation_time)
                            avail_cpu = machines[mid]['total_cpu'] - res_task['cpu'] - backfill_cpu
                            avail_mem = machines[mid]['total_mem'] - res_task['memory'] - backfill_mem
                            fits_at_reserved = (task['cpu'] <= avail_cpu and task['memory'] <= avail_mem)
                            if not (finishes_by or fits_at_reserved):
                                continue

                    if can_fit(task, mid, cpu_avail, mem_avail):
                        running[mid][tid] = t
                        machine_free_cpu[mid] -= task['cpu']
                        machine_free_mem[mid] -= task['memory']
                        task['_start_time'] = t
                        add_finish_event(tid, mid, t)
                        outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                        placed = True
                        changed = True
                        if reservation_machine is not None and mid == reservation_machine:
                            backfill_cpu += task['cpu']
                            backfill_mem += task['memory']
                        break

                if placed:
                    continue

                # b. Preemption
                if reservation_task is None and task['priority'] >= 9:
                    for mid in sorted_mids:
                        if not machine_up[mid]:
                            continue
                        ft_tasks = [x for x in running[mid] if task_info[x]['priority'] in (0, 1)]
                        ft_tasks.sort(key=evict_sort_key)

                        sim_cpu = machine_free_cpu[mid]
                        sim_mem = machine_free_mem[mid]
                        evict_list = []
                        for et in ft_tasks:
                            sim_cpu += task_info[et]['cpu']
                            sim_mem += task_info[et]['memory']
                            evict_list.append(et)
                            if sim_cpu >= task['cpu'] and sim_mem >= task['memory']:
                                break

                        if sim_cpu >= task['cpu'] and sim_mem >= task['memory']:
                            for et in evict_list:
                                et_task = task_info[et]
                                machine_free_cpu[mid] += et_task['cpu']
                                machine_free_mem[mid] += et_task['memory']
                                del running[mid][et]
                                et_task['_start_time'] = None
                                outcomes.append({"time": t, "kind": "task_evict", "entities": [et, mid], "value": None})
                                newly_waiting.append(et)
                            running[mid][tid] = t
                            machine_free_cpu[mid] -= task['cpu']
                            machine_free_mem[mid] -= task['memory']
                            task['_start_time'] = t
                            add_finish_event(tid, mid, t)
                            outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                            placed = True
                            changed = True
                            break
                if placed:
                    continue

                # c. Reservation
                if reservation_task is None:
                    fits_anywhere = False
                    for mid in sorted_mids:
                        if machine_up[mid]:
                            if machines[mid]['total_cpu'] >= task['cpu'] and machines[mid]['total_mem'] >= task['memory']:
                                fits_anywhere = True
                                break
                    if fits_anywhere:
                        best_time = None
                        best_mid = None
                        for mid in sorted_mids:
                            if not machine_up[mid]:
                                continue
                            earliest = t
                            for r_tid, r_started in running[mid].items():
                                finish = r_started + task_info[r_tid]['run_time']
                                if finish > earliest:
                                    earliest = finish
                            if best_time is None or earliest < best_time:
                                best_time = earliest
                                best_mid = mid
                        if best_time is not None:
                            reservation_task = tid
                            reservation_machine = best_mid
                            reservation_time = best_time
                            changed = True

            for tid in waiting:
                task = task_info[tid]
                if task.get('_start_time') is None:
                    still_waiting.append(tid)
            waiting = still_waiting + newly_waiting
            waiting.sort(key=queue_key)

    # Initialize globals for scheduling_round
    reservation_task = None
    reservation_machine = None
    reservation_time = None
    backfill_cpu = 0
    backfill_mem = 0

    while event_heap:
        t = heapq.heappop(event_heap)
        if t > horizon:
            break
        if t in processed_times:
            continue
        processed_times.add(t)

        process_finishes(t)
        process_failures(t)
        process_returns(t)
        process_submissions(t)
        scheduling_round(t)

    return [o for o in outcomes if o['time'] >= start]

