import heapq

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None: start = 0
    if horizon is None: horizon = params.get('window_length', 1200)

    machines = {}
    task_submits = []
    for inp in inputs:
        if inp['kind'] == 'machine_spec':
            mid = inp['entities'][0]
            machines[mid] = {
                'total_cpu': inp['fields']['CPU'],
                'total_mem': inp['fields']['memory'],
                'free_cpu': inp['fields']['CPU'],
                'free_mem': inp['fields']['memory'],
                'up': True,
                'fails_at': inp['fields']['fails_at'],
                'returns_at': inp['fields']['returns_at'],
                'running': {}
            }
        elif inp['kind'] == 'task_submit':
            task_submits.append(inp)

    sorted_mids = sorted(machines.keys())
    tasks = {}
    waiting = []
    outcomes = []

    def parse_tid(t_str):
        return int(''.join(filter(str.isdigit, t_str)))

    def q_key(tid):
        t = tasks[tid]
        return (-t['priority'], t['submit_time'], parse_tid(tid))

    def evict_key(tid):
        t = tasks[tid]
        return (t['priority'], -t['started_at'], -parse_tid(tid))

    event_heap = [0]
    for ts in task_submits:
        heapq.heappush(event_heap, ts['time'])
    for m in machines.values():
        if m['fails_at'] is not None: heapq.heappush(event_heap, m['fails_at'])
        if m['returns_at'] is not None: heapq.heappush(event_heap, m['returns_at'])

    processed = set()
    current_time = 0
    reservation = None
    backfill_used = {'cpu': 0, 'memory': 0}

    def try_schedule():
        nonlocal waiting, reservation, backfill_used
        reservation = None
        backfill_used = {'cpu': 0, 'memory': 0}
        if not waiting: return

        waiting.sort(key=q_key)
        changed = True
        while changed:
            changed = False
            to_remove = set()
            for idx, tid in enumerate(waiting):
                task = tasks[tid]
                if task['status'] != 'waiting':
                    to_remove.add(tid)
                    continue

                placed = False
                # a. First fit
                for mid in sorted_mids:
                    m = machines[mid]
                    if not m['up']: continue
                    can_place = (m['free_cpu'] >= task['cpu'] and m['free_mem'] >= task['memory'])
                    if reservation and mid == reservation[1]:
                        res_tid, res_mid, res_time = reservation
                        res_task = tasks[res_tid]
                        finishes_by_res = (current_time + task['run_time'] <= res_time)
                        avail_cpu = m['total_cpu'] - res_task['cpu'] - backfill_used['cpu']
                        avail_mem = m['total_mem'] - res_task['memory'] - backfill_used['memory']
                        fits_at_res = (task['cpu'] <= avail_cpu and task['memory'] <= avail_mem)
                        can_place = can_place and (finishes_by_res or fits_at_res)

                    if can_place:
                        m['free_cpu'] -= task['cpu']
                        m['free_mem'] -= task['memory']
                        m['running'][tid] = current_time
                        task['status'] = 'running'
                        task['started_at'] = current_time
                        task['machine'] = mid
                        if reservation and mid == reservation[1]:
                            backfill_used['cpu'] += task['cpu']
                            backfill_used['memory'] += task['memory']
                        outcomes.append({"time": current_time, "kind": "task_start", "entities": [tid, mid], "value": None})
                        heapq.heappush(event_heap, current_time + task['run_time'])
                        placed = True
                        changed = True
                        break

                if placed: continue

                # b. Preemption
                if not placed and not reservation and task['priority'] >= 9:
                    for mid in sorted_mids:
                        m = machines[mid]
                        if not m['up']: continue
                        ft_tasks = [t for t in m['running'] if tasks[t]['priority'] in (0, 1)]
                        ft_tasks.sort(key=evict_key)
                        sim_cpu = m['free_cpu']
                        sim_mem = m['free_mem']
                        evict_list = []
                        for et in ft_tasks:
                            sim_cpu += tasks[et]['cpu']
                            sim_mem += tasks[et]['memory']
                            evict_list.append(et)
                            if sim_cpu >= task['cpu'] and sim_mem >= task['memory']:
                                break
                        if sim_cpu >= task['cpu'] and sim_mem >= task['memory']:
                            for et in evict_list:
                                et_task = tasks[et]
                                m['free_cpu'] += et_task['cpu']
                                m['free_mem'] += et_task['memory']
                                del m['running'][et]
                                et_task['status'] = 'waiting'
                                et_task['started_at'] = None
                                et_task['machine'] = None
                                outcomes.append({"time": current_time, "kind": "task_evict", "entities": [et, mid], "value": None})
                                waiting.append(et)
                            m['free_cpu'] -= task['cpu']
                            m['free_mem'] -= task['memory']
                            m['running'][tid] = current_time
                            task['status'] = 'running'
                            task['started_at'] = current_time
                            task['machine'] = mid
                            outcomes.append({"time": current_time, "kind": "task_start", "entities": [tid, mid], "value": None})
                            heapq.heappush(event_heap, current_time + task['run_time'])
                            placed = True
                            changed = True
                            break
                if placed: continue

                # c. Reservation
                if not placed and not reservation:
                    fits_anywhere = False
                    for mid in sorted_mids:
                        m = machines[mid]
                        if m['up'] and m['total_cpu'] >= task['cpu'] and m['total_mem'] >= task['memory']:
                            fits_anywhere = True
                            break
                    if fits_anywhere:
                        best_time = None
                        best_mid = None
                        for mid in sorted_mids:
                            m = machines[mid]
                            if not m['up']: continue
                            earliest = current_time
                            for r_tid, r_start in m['running'].items():
                                finish = r_start + tasks[r_tid]['run_time']
                                if finish > earliest: earliest = finish
                            if best_time is None or earliest < best_time or (earliest == best_time and mid < best_mid):
                                best_time = earliest
                                best_mid = mid
                        if best_time is not None:
                            reservation = (tid, best_mid, best_time)
                            changed = True

        waiting = [t for t in waiting if tasks[t]['status'] == 'waiting']

    while event_heap:
        t = heapq.heappop(event_heap)
        if t > horizon: break
        if t in processed: continue
        processed.add(t)
        current_time = t

        # 1. Finishes
        for mid in sorted_mids:
            m = machines[mid]
            for tid, start in list(m['running'].items()):
                if start + tasks[tid]['run_time'] == t:
                    m['free_cpu'] += tasks[tid]['cpu']
                    m['free_mem'] += tasks[tid]['memory']
                    del m['running'][tid]
                    tasks[tid]['status'] = 'finished'
                    outcomes.append({"time": t, "kind": "task_finish", "entities": [tid, mid], "value": None})

        # 2. Failures
        for mid in sorted_mids:
            m = machines[mid]
            if m['fails_at'] == t:
                m['up'] = False
                for tid in list(m['running'].keys()):
                    m['free_cpu'] += tasks[tid]['cpu']
                    m['free_mem'] += tasks[tid]['memory']
                    del m['running'][tid]
                    tasks[tid]['status'] = 'waiting'
                    tasks[tid]['started_at'] = None
                    tasks[tid]['machine'] = None
                    outcomes.append({"time": t, "kind": "task_fail", "entities": [tid, mid], "value": None})
                    waiting.append(tid)

        # 3. Returns
        for mid in sorted_mids:
            m = machines[mid]
            if m['returns_at'] == t:
                m['up'] = True
                m['free_cpu'] = m['total_cpu']
                m['free_mem'] = m['total_mem']
                m['running'] = {}

        # 4. Submissions
        for ts in task_submits:
            if ts['time'] == t:
                tid = ts['entities'][0]
                tasks[tid] = {
                    'priority': ts['fields']['priority'],
                    'cpu': ts['fields']['CPU'],
                    'memory': ts['fields']['memory'],
                    'run_time': ts['fields']['run_time'],
                    'submit_time': t,
                    'status': 'waiting',
                    'started_at': None,
                    'machine': None
                }
                waiting.append(tid)

        # 5. Scheduling round
        try_schedule()

    return [o for o in outcomes if o['time'] > start]

